client_script:
function onClick() {
    var ga = new GlideAjax('SupplierTaskAjax');
    ga.addParam('sysparm_name', 'getTaskDefaults');
    ga.addParam('sysparm_table', g_form.getTableName());
    ga.addParam('sysparm_parent', g_form.getUniqueValue());
    ga.getXMLAnswer(function(answer) {
        var defaults = {};
        try {
            defaults = JSON.parse(answer || '{}');
        } catch (e) {
            defaults = {};
        }
        getMessages(['Create Supplier Task', 'Supplier', 'Short description', 'Description', 'Work notes to Supplier', 'Include attachments', 'Cancel', 'Create', 'Supplier task created', 'Could not create supplier task', 'No supplier groups found'], function(messages) {
            openModal(messages, defaults);
        });
    });

    function openModal(messages, defaults) {
        var suppliers = defaults.suppliers || [];
        if (!suppliers.length) {
            g_form.addErrorMessage(messages['No supplier groups found']);
            return;
        }
        g_modal.showFields({
            title: messages['Create Supplier Task'],
            size: 'md',
            fields: [{
                type: 'choice',
                name: 'supplier',
                label: messages['Supplier'],
                mandatory: true,
                choices: suppliers
            }, {
                type: 'string',
                name: 'short_description',
                label: messages['Short description'],
                mandatory: true,
                value: defaults.short_description || ''
            }, {
                type: 'textarea',
                name: 'description',
                label: messages['Description'],
                value: defaults.description || ''
            }, {
                type: 'textarea',
                name: 'work_notes',
                label: messages['Work notes to Supplier'],
                mandatory: true
            }, {
                type: 'boolean',
                name: 'include_attachments',
                label: messages['Include attachments'],
                value: true,
                readonly: true
            }],
            cancelTitle: messages['Cancel'],
            confirmTitle: messages['Create'],
            confirmType: 'confirm'
        }).then(function(fieldValues) {
            var ajax = new GlideAjax('SupplierTaskAjax');
            ajax.addParam('sysparm_name', 'createTask');
            ajax.addParam('sysparm_table', g_form.getTableName());
            ajax.addParam('sysparm_parent', g_form.getUniqueValue());
            ajax.addParam('sysparm_supplier', getModalFieldValue(fieldValues, 'supplier'));
            ajax.addParam('sysparm_short_description', getModalFieldValue(fieldValues, 'short_description'));
            ajax.addParam('sysparm_description', getModalFieldValue(fieldValues, 'description'));
            ajax.addParam('sysparm_work_notes', getModalFieldValue(fieldValues, 'work_notes'));
            ajax.getXMLAnswer(function(result) {
                if (result && result.indexOf('success:') === 0) {
                    g_form.addInfoMessage(messages['Supplier task created'] + ': ' + result.substring(8));
                    g_form.reload();
                } else {
                    g_form.addErrorMessage(messages['Could not create supplier task'] + ': ' + (result || ''));
                }
            });
        });
    }

    function getModalFieldValue(fieldValues, name) {
        var fields = fieldValues && (fieldValues.updatedFields || fieldValues.fields) || [];
        for (var i = 0; i < fields.length; i++) {
            if (fields[i].name === name)
                return fields[i].value;
        }
        return '';
    }
}
